  function stepRest(a,p){if(p.phase==='chooseSurface'){const t=SP.restTargets(state,a).filter(x=>x.id!==p.excludeTarget)[0];if(t){p.restTarget={...t};if(t.kind==='slot'&&!reserve(`slot:${t.id}`,a)){p.excludeTarget=t.id;return;}p.phase='move';return;}p.restTarget={kind:'standing',position:{...a.position},quality:.18,posture:'standing'};p.phase='settle';return;}if(p.phase==='move'){const t=p.restTarget;if(t.kind==='slot'&&!reserve(`slot:${t.id}`,a)){p.excludeTarget=t.id;p.phase='chooseSurface';return;}if(!moveToExact(a,t.position,'前往休息位置'))return;p.phase='settle';return;}if(p.phase==='settle'){const t=p.restTarget;if(t.kind==='slot'){const slot=SP.getSlot(state,t.id);if(!slot||!atSpatialPosition(a,t.position)||!SP.slotApproachNodes?.(state,slot,a,'walk').some(node=>atSpatialPosition(a,node))){p.phase='chooseSurface';return;}if(t.posture==='lying')lieDown(a,slot);else sitOn(a,slot);}else if(t.posture==='lying')lieDown(a);else standUp(a);p.phase='resting';p.restTicks=0;p.targetFatigue=a.kind==='cat'?18:20;const postureText=a.posture.kind==='sitting'?`坐在${state.furniture[a.posture.furnitureId]?.name||'座位'}`:a.posture.kind==='lying'?(a.posture.furnitureId?`躺在${state.furniture[a.posture.furnitureId]?.name||'休息處'}`:a.kind==='cat'?'蜷下身體':'躺下'):'停下來';addEvent(`${a.name}${postureText}休息。`,'normal',[],{actor:a.id,action:'rest',posture:a.posture.kind,position:positionRef(a.position)});return;}if(p.phase==='resting'){const info=restRecoveryInfo(a);p.restTicks++;if(info.noise>22&&p.restTicks<=4){const old=p.restTarget?.id;standUp(a);p.excludeTarget=old;p.phase='chooseSurface';addEvent(`${a.name}覺得這裡太吵，改找別的休息位置。`,'normal',[],{actor:a.id,action:'restReroute',noise:info.noise});return;}a.needs.fatigue=clamp(a.needs.fatigue-info.recovery);a.wellbeing.comfort=clamp(a.wellbeing.comfort+.12*info.restEfficiency);if(a.needs.fatigue<=p.targetFatigue||p.restTicks>=24)finishAction(a,{dropHeld:false});}}

