  function actionLabel(a){const extension=resolveActionLabel(a);if(extension)return extension;const p=a.action;if(!p)return'目前沒有進行中的行動';const motion=a.locomotion?.phase&&a.locomotion.phase!=='idle'?(a.locomotion.phase==='transition'?(a.locomotion.mode==='walk'?'・起身準備步行':`・切換為${locomotionRuntime()?.modeLabel?.(a.locomotion.mode)||a.locomotion.mode}姿勢`):`・${locomotionRuntime()?.modeLabel?.(a.locomotion.mode)||a.locomotion.mode}中`):'';const moveTarget=(p.spatialGoal?`・目標 (${p.spatialGoal.x},${p.spatialGoal.y})`:'')+motion;switch(p.kind){case'eat':{const plate=p.container?endpointName(p.container):'餐盤';if(p.phase==='toDish'||p.phase==='takeDish')return`吃東西・去拿${plate}${moveTarget}`;if(p.phase==='toFood'||p.phase==='serve')return`吃東西・用${plate}盛食物${moveTarget}`;if(p.phase==='chooseSeat')return`吃東西・端著${plate}找座位`;if(p.phase==='toSeat'||p.phase==='sit')return`吃東西・端著${plate}前往座位${moveTarget}`;if(p.phase==='standEat')return`吃東西・準備站著吃`;if(p.phase==='eatingPlate')return`吃東西・${plate}・進食中`;if(p.phase==='toDirectFood')return`吃東西・前往${p.foodSource?endpointName(p.foodSource):'食物'}${moveTarget}`;if(p.phase==='claimDirect'||p.phase==='eatingDirect')return`吃東西・${p.foodSource?endpointName(p.foodSource):'食物'}・進食中`;return`吃東西${moveTarget}`;}case'drinkWater':case'drinkAlcohol':return `${ZH[p.kind]}・${p.phase==='toVessel'?'去拿容器':p.phase==='toSource'?'前往來源':p.phase==='fill'?'裝取中':p.phase==='drink'?'飲用中':p.phase==='move'?'前往飲用來源':'準備中'}${p.container?`・${endpointName(p.container)}`:''}${moveTarget}`;case'rest':return p.phase==='resting'?`休息・${a.posture.kind==='sitting'?'坐著':a.posture.kind==='lying'?'躺／蜷著':'站著'}`:p.restTarget?`休息・前往${p.restTarget.kind==='slot'?targetLabel({kind:'slot',id:p.restTarget.id}):'休息位置'}`:'休息・尋找位置';case'sleep':return p.phase==='sleeping'?`睡眠・${p.sleepTarget?targetLabel({kind:'slot',id:p.sleepTarget.id}):'睡眠位置'}・熟睡中`:p.sleepTarget?`睡眠・前往${targetLabel({kind:'slot',id:p.sleepTarget.id})}${moveTarget}`:'睡眠・尋找位置';case'talk':return`找人聊天・${state.agents[p.targetAgent]?.name||''}${moveTarget}`;case'petAnimal':return`摸${state.agents[p.targetAgent]?.name||'動物'}${moveTarget}`;case'seekHuman':return`找人撒嬌${moveTarget}`;case'cleanFloor':return`清理地面${moveTarget}`;case'groom':return'舔毛清潔';case'wander':return`閒晃${moveTarget}`;case'restockContainer':return`補充資源・${endpointName(p.destinationId)}・${resourceName(p.resource)}・${p.carrierId?`${endpointName(p.carrierId)}・`:''}${p.phase}${moveTarget}`;case'externalSupply':return`外出補給・${p.carrierId?endpointName(p.carrierId)+'・':''}${p.phase}${moveTarget}`;default:return ZH[p.kind]||p.kind;}}
